package dev.veltraph.client.core;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Actual Core/AbstractModule ports only. No native key/history/source cause is mocked or claimed. */
final class ManualLogicalStopProvenanceTest {
 static class M extends AbstractModule {
  Runnable stop=()->{};int stops,legacyHooks;ModuleManager.OwnDisableReceipt legacy;
  M(String id){super(id,id,ModuleCategory.INTERNAL);}
  void pause(){setState(MacroState.PAUSED);}
  public void onDisable(){stops++;stop.run();}
  protected void postDisableNormalReturned(ModuleManager.OwnDisableReceipt actual){legacyHooks++;legacy=actual;}
 }
 static final class Observe implements ModuleManager.ManualStopObserver {
  int starts,ends;ModuleManager.ManualStopStart first;ModuleManager.ManualStopReceipt last;List<Module> owners=List.of();Runnable before=()->{},after=()->{};List<Boolean> ownerProofs;
  public Object before(ModuleManager.ManualStopStart actual){starts++;first=actual;assertTrue(actual.startingCurrent());before.run();return actual;}
  public void after(ModuleManager.ManualStopReceipt actual,Object original){ends++;last=actual;assertTrue(actual.matches((ModuleManager.ManualStopStart)original));assertTrue(actual.current());ownerProofs=owners.stream().map(actual::disabledOwnerFromStart).toList();after.run();}
 }
 @Test void actualStopAllConfirmsEachNormallyReturnedOriginalOwnerAndExpiresAfterCall(){var r=new ModuleManager();var a=new M("a");var b=new M("b");r.register(a);r.register(b);a.setEnabled(true);b.setEnabled(true);var o=new Observe();o.owners=List.of(a,b);r.observeManualStops(o);r.stopAll();assertEquals(List.of(true,true),o.ownerProofs);assertEquals(1,o.starts);assertEquals(1,o.ends);assertFalse(o.last.current());assertFalse(o.first.startingCurrent());assertEquals(1,a.stops);assertEquals(1,b.stops);}
 @Test void actualPausedStopGetsSeparateManualProofWithoutBroadeningLegacyG7(){var r=new ModuleManager();var a=new M("paused");r.register(a);a.setEnabled(true);a.pause();var o=new Observe();o.owners=List.of(a);r.observeManualStops(o);assertTrue(r.disable(a.id()));assertEquals(List.of(true),o.ownerProofs);assertEquals(0,a.legacyHooks);assertNull(a.legacy);assertFalse(a.isEnabled());}
 @Test void directNormalCompletionPreservesOriginalLegacyHookAndDoesNotIssueManualCause(){var r=new ModuleManager();var a=new M("normal");r.register(a);a.setEnabled(true);var o=new Observe();r.observeManualStops(o);a.setEnabled(false);assertEquals(0,o.starts);assertEquals(0,o.ends);assertEquals(1,a.legacyHooks);assertTrue(a.legacy.current());}
 @Test void actualToggleDisableUsesManualCauseButToggleEnableDoesNot(){var r=new ModuleManager();var a=new M("toggle");r.register(a);var o=new Observe();o.owners=List.of(a);r.observeManualStops(o);r.toggle(a.id());assertEquals(0,o.starts);r.toggle(a.id());assertEquals(1,o.starts);assertEquals(List.of(true),o.ownerProofs);}
 @Test void thrownDisableCannotMintNormalOwnerReturnEvenIfManagerSwallowsOriginalFailure(){var r=new ModuleManager();var a=new M("throws");r.register(a);a.setEnabled(true);a.stop=()->{throw new IllegalStateException("actual failure");};var o=new Observe();o.owners=List.of(a);r.observeManualStops(o);r.stopAll();assertEquals(0,o.ends);assertNull(o.ownerProofs);assertEquals(0,a.legacyHooks);assertFalse(a.isEnabled());}
 @Test void rawPublicDisableIsNotAnActualSetEnabledReturn(){var r=new ModuleManager();var a=new M("raw");r.register(a);a.setEnabled(true);var o=new Observe();r.observeManualStops(o);a.onDisable();assertEquals(0,o.starts);assertEquals(0,o.ends);assertTrue(a.isEnabled());}
 @Test void recursiveManualStopsRevokeBothWithoutRebasing(){var r=new ModuleManager();var a=new M("recursive");r.register(a);a.setEnabled(true);a.stop=r::stopAll;var o=new Observe();r.observeManualStops(o);r.stopAll();assertEquals(1,o.starts);assertEquals(0,o.ends);assertFalse(a.isEnabled());}
 @Test void newOwnerEnabledDuringDisableRevokesOriginalRetirement(){var r=new ModuleManager();var a=new M("old");var b=new M("new");r.register(a);r.register(b);a.setEnabled(true);a.stop=()->b.setEnabled(true);var o=new Observe();r.observeManualStops(o);r.disable(a.id());assertEquals(0,o.ends);assertTrue(b.isEnabled());assertFalse(a.isEnabled());}
 @Test void callbackReplacementAndRestorationCannotRebaseOriginalStop(){var r=new ModuleManager();var a=new M("aba");r.register(a);a.setEnabled(true);java.util.function.Consumer<Module> original=m->{};r.beforeDisable(original);a.stop=()->{r.beforeDisable(m->{});r.beforeDisable(original);};var o=new Observe();r.observeManualStops(o);r.stopAll();assertEquals(0,o.ends);assertFalse(a.isEnabled());}
 @Test void sourceObserverReplacementAndRosterMutationRefuse(){for(boolean roster:new boolean[]{false,true}){var r=new ModuleManager();var a=new M("mutation");r.register(a);a.setEnabled(true);var o=new Observe();r.observeManualStops(o);a.stop=()->{if(roster)r.register(new M("added"));else r.observeManualStops(new Observe());};r.stopAll();assertEquals(0,o.ends);assertFalse(a.isEnabled());}}
 @Test void beforeAndAfterObservationFailureDoNotAlterOriginalStopOrLegacyResult(){for(boolean initial:new boolean[]{false,true}){var r=new ModuleManager();var a=new M("observer-fault");r.register(a);a.setEnabled(true);var o=new Observe();if(initial)o.before=()->{throw new IllegalStateException("extra capture");};else o.after=()->{throw new IllegalStateException("extra completion");};r.observeManualStops(o);assertDoesNotThrow(r::stopAll);assertFalse(a.isEnabled());assertEquals(1,a.legacyHooks);assertTrue(a.legacy.current());}}
 @Test void anotherActorFailureCannotPromoteSuccessfulOldOwnerReturnToAggregateStop(){var r=new ModuleManager();var a=new M("successful-old");var b=new M("failed-other");r.register(a);r.register(b);a.setEnabled(true);b.setEnabled(true);b.stop=()->{throw new IllegalStateException("other cleanup failed");};var o=new Observe();o.owners=List.of(a);r.observeManualStops(o);r.stopAll();assertEquals(1,a.legacyHooks);assertEquals(0,o.ends);assertFalse(a.isEnabled());assertFalse(b.isEnabled());}
 @Test void ambiguousActualRegistryHasNoAuthenticatedManualReturn(){var r=new ModuleManager();var other=new ModuleManager();var a=new M("ambiguous");r.register(a);other.register(a);a.setEnabled(true);var o=new Observe();r.observeManualStops(o);r.stopAll();assertFalse(a.isEnabled());assertEquals(0,o.ends);assertEquals(0,a.legacyHooks);}
 @Test void stillEnabledPassiveActorMakesStrictNoOwnerProofUnavailable(){var r=new ModuleManager();var a=new M("owner");var passive=new M("passive"){@Override public boolean isPassiveObserver(){return true;}};r.register(a);r.register(passive);a.setEnabled(true);passive.setEnabled(true);var o=new Observe();r.observeManualStops(o);r.disable(a.id());assertFalse(a.isEnabled());assertTrue(passive.isEnabled());assertEquals(0,o.ends);}
}
